    const manifest = exported.manifest;
    await this.ledger.append({
      operationId,
      tenantId,
      tenantSchema,
      rangeStart,
      rangeEnd,
      state: 'EXPORTED',
      objectKey,
      sourceRowCount: String(manifest.sourceRowCount),
      sourceSnapshot: manifest.sourceSnapshot,
      parquetSha256: manifest.sha256,
      actor,
    });

