          ORDER BY time, sensor_id, channel_id
          LIMIT $3 OFFSET $4`,
        [rangeStart, rangeEnd, EXPORT_PAGE_SIZE, offset],
      );
      if (rows.length === 0) return;
      for (const row of rows) yield toArchiveRow(row);
      if (rows.length < EXPORT_PAGE_SIZE) return;
    }
  }
