import { Repository, DataSource, EntityManager, In, LessThan } from 'typeorm';
import {
  listActiveTenantSchemaIdentities,
  runInTenantTransaction,
  tenantManagerRepo,
} from '@aquaculture/backend-common/database';
import { createStandardPaginatedResult, IStandardPaginatedResult } from '@aquaculture/backend-common/pagination';

import {
  formatValidationErrors,
  validateCommandEnvelope,
  validateDeployProgramParams,
} from '@platform/sensor-contracts/validators';

import { ArtifactService } from '../deploy-artifact/artifact.service';
import { DeployArtifactType } from '../deploy-artifact/entities/deploy-artifact.entity';
import { EdgeDeviceService } from '../edge-device/edge-device.service';
import { DeviceIoConfig } from '../edge-device/entities/device-io-config.entity';
import { MqttClientService } from '../shared-mqtt/mqtt-client.service';

import { AutomationEventsPublisher } from './events/automation-events.publisher';
import { DeploymentLogService } from './services/deployment-log.service';
import {
  CreateProgramInput,
  UpdateProgramInput,
  ProgramFilterInput,
