    dayOfWeek: weekday,
    date,
    entryType: 'work',
    shiftCode: pattern,
    shiftName: pattern === 'S' ? 'Sabah' : 'Akşam',
    startTime: pattern === 'S' ? '08:00:00' : '16:00:00',
